import bpy, os
prefs = bpy.context.preferences
cy = prefs.addons.get('cycles')
devs = []
if cy:
    cp = cy.preferences
    try:
        cp.refresh_devices()
    except Exception as e:
        devs.append(str(e))
    devs += [(d.name, d.type, d.use) for d in cp.devices]
result = {"version": bpy.app.version_string, "cwd": os.getcwd(), "objects": [o.name for o in bpy.data.objects],
          "engine": bpy.context.scene.render.engine, "devices": devs, "fonts":[f.name for f in bpy.data.fonts]}
